      "code": {
        "lang": "Python / Lab",
        "pseudo": "// Null lead offset -> measure Kelvin V_sense -> cross-check DMM/DAQ against PMBus",
        "code": "import csv, time\nfrom datetime import datetime, timezone\nimport pyvisa\nimport matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\n\ndef log_and_plot_power(resource_str: str, samples: int = 60, interval_s: float = 0.5, out_csv: str = 'power_log.csv'):\n    rm = pyvisa.ResourceManager()\n    daq = rm.open_resource(resource_str)\n    daq.timeout = 5000\n    times, powers = [], []\n    try:\n        with open(out_csv, 'w', newline='', encoding='utf-8') as f:\n            writer = csv.writer(f)\n            writer.writerow(['utc_ts', 'elapsed_s', 'voltage_v', 'current_a', 'power_w'])\n            t0 = time.monotonic()\n            for _ in range(samples):\n                v = float(daq.query('MEAS:VOLT:DC? (@101)').strip())\n                i = float(daq.query('MEAS:CURR:DC? (@102)').strip())\n                p = v * i\n                elapsed = round(time.monotonic() - t0, 3)\n                writer.writerow([datetime.now(timezone.utc).isoformat(), elapsed, v, i, round(p, 6)])\n                f.flush()\n                times.append(elapsed); powers.append(p)\n                time.sleep(interval_s)\n    finally:\n        daq.close(); rm.close()\n    plt.figure(figsize=(9, 4))\n    plt.plot(times, powers, marker='o', markersize=2)\n    plt.xlabel('Elapsed Time (s)'); plt.ylabel('Power (W)'); plt.title('DUT Rail Power vs Time')\n    plt.grid(True); plt.tight_layout(); plt.savefig('power_plot.png')"
      },
